for service, c in measured["containers"].items():
    for i, s in enumerate(c["segments"], 1):
        if s["peak_bytes"] > c["budget_bytes"]:
            misses.append(f"{service} segment {i}: memory.peak {size(s['peak_bytes'])}, above its "
                          f"{size(c['budget_bytes'])} budget")
    for event in ("oom", "oom_kill"):
        if c["events"][event]:
            misses.append(f"{service}: {c['events'][event]} {event} event(s) during the run")

def against(criterion: str, value: int | None) -> None:
    threshold = PROPOSED.get(criterion)
    proposed.append({"criterion": criterion, "value": value, "threshold": threshold,
                     "met": None if threshold is None else value is not None and value <= threshold})

for service, c in measured["containers"].items():
    against(f"{service} anon", c["anon_bytes"])
    against(f"{service} limit hits", c["events"]["max"])
for step, peak in sorted(measured["steps"].items()):
    against(f"step {step}", peak)
for name in ROLES:
    p = measured["processes"][name]
    against(f"process {name}", p["rss_bytes"] if p["processes"] else None)
return {"counts": not invalid, "passed": not invalid and not misses, "invalid": invalid, "misses": misses,
        "proposed": proposed}

